CREATE TABLE IF NOT EXISTS organizations (id TEXT PRIMARY KEY,name TEXT NOT NULL,slug TEXT UNIQUE NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE,employee_limit INTEGER NOT NULL DEFAULT 25,inventory_limit INTEGER NOT NULL DEFAULT 10000,plan TEXT NOT NULL DEFAULT 'PRO',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,name TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN('ADMIN','EMPLOYEE')),organization_id TEXT REFERENCES organizations(id),is_super_admin BOOLEAN NOT NULL DEFAULT FALSE,team TEXT,active BOOLEAN NOT NULL DEFAULT TRUE,daily_limit INTEGER NOT NULL DEFAULT 20,can_manage_accounting BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS services (id TEXT PRIMARY KEY,organization_id TEXT NOT NULL REFERENCES organizations(id),name TEXT NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE,default_daily_limit INTEGER NOT NULL DEFAULT 10,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(organization_id,name));
CREATE TABLE IF NOT EXISTS employee_service_permissions (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,service_id TEXT NOT NULL REFERENCES services(id) ON DELETE CASCADE,enabled BOOLEAN NOT NULL DEFAULT TRUE,daily_limit INTEGER NOT NULL DEFAULT 5,PRIMARY KEY(user_id,service_id));
CREATE TABLE IF NOT EXISTS inventory_items (id TEXT PRIMARY KEY,organization_id TEXT NOT NULL REFERENCES organizations(id),service_id TEXT NOT NULL REFERENCES services(id),email TEXT NOT NULL,password TEXT NOT NULL,otp_secret TEXT,otp_url TEXT,account_type TEXT NOT NULL CHECK(account_type IN('INDIVIDUAL','SHARED')),max_usage INTEGER NOT NULL DEFAULT 1,current_usage INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'AVAILABLE',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(service_id,email));
CREATE TABLE IF NOT EXISTS withdrawals (id TEXT PRIMARY KEY,organization_id TEXT NOT NULL REFERENCES organizations(id),user_id TEXT NOT NULL REFERENCES users(id),service_id TEXT NOT NULL REFERENCES services(id),inventory_item_id TEXT REFERENCES inventory_items(id),status TEXT NOT NULL,idempotency_key TEXT UNIQUE NOT NULL,previous_usage INTEGER,new_usage INTEGER,batch_id TEXT,batch_quantity INTEGER NOT NULL DEFAULT 1,customer_name TEXT,customer_phone TEXT,customer_contact TEXT,customer_reference TEXT,customer_notes TEXT,subscription_start_date DATE,subscription_months INTEGER,subscription_end_date DATE,warranty_days INTEGER NOT NULL DEFAULT 0,warranty_end_date DATE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS activity_logs (id TEXT PRIMARY KEY,organization_id TEXT REFERENCES organizations(id),actor_id TEXT,action TEXT NOT NULL,entity_type TEXT,entity_id TEXT,metadata JSONB NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS withdrawals_user_created_idx ON withdrawals(user_id,created_at);
CREATE INDEX IF NOT EXISTS inventory_available_idx ON inventory_items(service_id,status,created_at);
CREATE INDEX IF NOT EXISTS users_org_idx ON users(organization_id);
CREATE INDEX IF NOT EXISTS services_org_idx ON services(organization_id);
